const vd = (dc, dr) => Math.hypot((dc - dr) * TW / 2, (dc + dr) * TH / 2) / TW;
const dia = (x, y, w = 1) => `M${x},${y - TH * w} L${x + TW * w / 2},${y - TH * w / 2} L${x},${y} L${x - TW * w / 2},${y - TH * w / 2} Z`;

/* ── 계화식 상자 · 지붕 ── */
function box(H, w = 1) {
  const hw = TW * w / 2, hh = TH * w / 2;
  return P(`M${-hw},${-hh} L0,0 L0,${-H} L${-hw},${-hh - H} Z`, "side")
       + P(`M0,0 L${hw},${-hh} L${hw},${-hh - H} L0,${-H} Z`, "dark")
       + P(`M0,${-TH * w - H} L${hw},${-hh - H} L0,${-H} L${-hw},${-hh - H} Z`, "fillp");
}
function hip(H, R, w = 1, ov = 1.2) {                          // 모임지붕 (초가)
  const hw = TW * w * ov / 2, hh = TH * w * ov / 2, ap = -H - TH * w / 2 - R;
  return P(`M${-hw},${-hh - H} L0,${-H + 2} L0,${ap} Z`, "roof") + P(`M0,${-H + 2} L${hw},${-hh - H} L0,${ap} Z`, "roofd");
}
function cone(H, R, w = 1) {                                   // 원뿔 (막집 · 움집)
  const hw = TW * w / 2, hh = TH * w / 2, ap = -H - hh - R;
  return P(`M${-hw},${-hh - H} Q${-hw * .55},${ap + R * .4} 0,${ap} Q${hw * .55},${ap + R * .4} ${hw},${-hh - H} Q0,${-hh - H + hh} ${-hw},${-hh - H} Z`, "fillp")
       + P(`M${-hw * .45},${-hh - H - 2} Q${-hw * .26},${ap + R * .5} 0,${ap}`, "thin")
       + P(`M${hw * .45},${-hh - H - 2} Q${hw * .26},${ap + R * .5} 0,${ap}`, "thin");
}
